    const g = ctx.createRadialGradient(x - r * 0.35, y - r * 0.4, r * 0.1, x, y, r * 1.05);
    g.addColorStop(0, '#ffffff'); g.addColorStop(0.55, '#f4ece6'); g.addColorStop(0.85, '#e5b9ae'); g.addColorStop(1, '#a8615a');
