    '>': '01000 00100 00010 00001 00010 00100 01000', '<': '00010 00100 01000 10000 01000 00100 00010', '*': '00000 00100 10101 01110 10101 00100 00000',
    '@': '01110 10001 10111 10101 10111 10000 01110', '_': '00000 00000 00000 00000 00000 00000 11111', '&': '01100 10010 10100 01000 10101 10010 01101',
